module max_ranks (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] a_0, a_1,\n    input wire [31:0] b_0, b_1,\n    input wire [31:0] K,\n    output reg [1:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 2'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (((a_0 + K) < a_1 && (b_1 + K) < b_0) || ((a_1 + K) < a_0 && (b_0 + K) < b_1))\n                        result <= 2'd1;\n                    else\n                        result <= 2'd2;\n                    state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule